/**
 * Service worker registration (client only). The SW (out/sw.js) is generated by
 * scripts/pwa/build.ts after `next build`, so it only exists in the static export: in
 * `next dev` we unregister any SW left over from serving out/ on the same port.
 *
 * New versions: the browser (or "Buscar actualización", `checkForUpdate`) fetches sw.js; when it
 * changed, the new SW downloads the whole app for offline use before it can take over. Follow it
 * with `useUpdateStatus()`: "downloading" (with the SW's INSTALL_PROGRESS counts), "ready" (call
 * `apply()`: the new version takes over and the page reloads), "failed" (download stopped; the
 * next check starts again).
 */

import { useSyncExternalStore } from "react";
import { getActiveLang } from "@/lib/content/active";
import { getAudioProgress } from "./audio-cache";

export const SW_URL = "/sw.js";

/** Same name in scripts/pwa/sw.template.js. */
const INSTALL_PROGRESS = "INSTALL_PROGRESS";

export type UpdateStatus =
  /** No new version known (none found, or no SW: dev, unsupported browser). */
  | { state: "idle" }
  /** A new version is downloading: `done` of `total` files stored (total 0 = no news yet). */
  | { state: "downloading"; done: number; total: number }
  /** Downloaded and waiting: `apply()` activates it and reloads the page. */
  | { state: "ready"; worker: ServiceWorker; apply: () => void }
  /** The last download stopped (offline, server error); the next check starts it again. */
  | { state: "failed" };

const IDLE: UpdateStatus = { state: "idle" };
let status: UpdateStatus = IDLE;
const listeners = new Set<() => void>();

function setStatus(next: UpdateStatus) {
  status = next;
  listeners.forEach((l) => l());
}

export function getUpdateStatus(): UpdateStatus {
  return status;
}

export function subscribeUpdateStatus(onChange: () => void): () => void {
  listeners.add(onChange);
  return () => {
    listeners.delete(onChange);
  };
}

/** React: the current new-version status (stable object until it changes). */
export function useUpdateStatus(): UpdateStatus {
  return useSyncExternalStore(subscribeUpdateStatus, getUpdateStatus, () => IDLE);
}

let started = false;
/** Reload only when the user accepted an update (not when the very first SW takes control). */
let accepted = false;
/** The new SW being followed (installing or waiting). */
let tracked: ServiceWorker | null = null;

function ready(worker: ServiceWorker) {
  if (status.state === "ready" && status.worker === worker) return;
  setStatus({
    state: "ready",
    worker,
    apply: () => {
      accepted = true;
      worker.postMessage({ type: "SKIP_WAITING" });
    },
  });
}

/** Follows the new version in `reg` (installing, else waiting). Not on first install: no update then. */
function track(reg: ServiceWorkerRegistration) {
  const sw = navigator.serviceWorker;
  if (!sw.controller) return;
  const worker = reg.installing ?? reg.waiting;
  if (!worker || worker === tracked) return;
  tracked = worker;
  const onState = () => {
    if (tracked !== worker) return;
    if (worker.state === "installed") ready(worker);
    else if (worker.state === "installing" && status.state !== "downloading") {
      setStatus({ state: "downloading", done: 0, total: 0 });
    } else if (worker.state === "redundant") {
      // Its download failed (or a newer one replaced it): fall back to a version still waiting.
      tracked = null;
      if (reg.waiting) track(reg);
      else if (status.state === "downloading") setStatus({ state: "failed" });
    }
  };
  worker.addEventListener("statechange", onState);
  onState();
}

/**
 * Registers the SW once and follows new versions (`useUpdateStatus`). Called by `UpdatePrompt`.
 */
export function registerServiceWorker(): void {
  if (started || typeof navigator === "undefined" || !("serviceWorker" in navigator)) return;
  started = true;
  const sw = navigator.serviceWorker;

  if (process.env.NODE_ENV !== "production") {
    sw.getRegistrations().then((regs) => regs.forEach((r) => r.unregister()));
    return;
  }

  sw.addEventListener("controllerchange", () => {
    if (accepted) window.location.reload();
  });

  // Only an installing SW sends these, and only one installs at a time.
  sw.addEventListener("message", (event: MessageEvent) => {
    const d: unknown = event.data;
    if (!d || typeof d !== "object" || (d as { type?: unknown }).type !== INSTALL_PROGRESS) return;
    if (status.state !== "downloading") return;
    const m = d as Record<string, unknown>;
    setStatus({ state: "downloading", done: Number(m.done) || 0, total: Number(m.total) || 0 });
  });

  sw.register(SW_URL)
    .then((reg) => {
      track(reg);
      reg.addEventListener("updatefound", () => track(reg));
      // Check for a new version whenever the app comes back to the foreground.
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "visible" && !reg.installing) reg.update().catch(() => {});
      });
    })
    .catch(() => {
      // No SW (unsupported, http on a LAN address...): the app still works online.
    });

  // Ask the browser not to evict the offline copy (best effort).
  navigator.storage?.persist?.().catch(() => {});
}

/** "found": a new version is downloading or ready (see `useUpdateStatus`). */
export type UpdateCheck = "found" | "latest" | "offline" | "unavailable";

/**
 * Asks the server for a new version now (the user tapped "Buscar actualización"). Only fetches
 * sw.js, so it answers fast; a version found then downloads in the background.
 */
export async function checkForUpdate(): Promise<UpdateCheck> {
  if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return "unavailable";
  const sw = navigator.serviceWorker;
  const reg = await sw.getRegistration();
  if (!reg || !sw.controller) return "unavailable";
  // Already downloading or downloaded: nothing to ask.
  if (!reg.installing && !reg.waiting) {
    try {
      await reg.update();
    } catch {
      return "offline";
    }
  }
  if (!reg.installing && !reg.waiting) return "latest";
  track(reg);
  return "found";
}

export type OfflineStatus = "ready" | "downloading" | "unavailable";

/**
 * Whether the app (pages) and the active language's audio are stored for offline use on this
 * device. Other languages' audio is not kept (see `./audio-cache`).
 */
export async function offlineStatus(): Promise<OfflineStatus> {
  if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return "unavailable";
  const reg = await navigator.serviceWorker.getRegistration();
  if (!reg) return "unavailable";
  // A SW only becomes active once its install (the full precache) succeeded.
  if (reg.active) return getAudioProgress().state === "ready" || !getActiveLang() ? "ready" : "downloading";
  return reg.installing || reg.waiting ? "downloading" : "unavailable";
}
